import { readFile, writeFile } from 'node:fs/promises';

const directory=new URL('../supabase/',import.meta.url);
const files=['setup.sql','membership.sql'];
const sections=await Promise.all(files.map(async name=>{
  const sql=await readFile(new URL(name,directory),'utf8');
  return `-- Source: ${name}\n${sql.replace(/^(begin|commit);\s*$/gmi,'').trim()}`;
}));
const header=`-- DMKD Lab: one-time installation for a fresh Supabase project.
-- Target project: geqkimegnprqipooaqvr
-- First administrator: first-admin@example.com (email verification required).
-- Generated by scripts/prepare-supabase.mjs; edit the source SQL files instead.
-- This transaction creates the lab schema, policies, storage bucket, and admin RPCs.
-- Existing same-name objects cause an error and rollback; they are not overwritten.
begin;\n\n`;
await writeFile(new URL('install.sql',directory),header+sections.join('\n\n')+'\n\ncommit;\n');
console.log('Prepared supabase/install.sql');
